-- Purpose-limited accounting, source approval and immutability; entirely rolled back.
begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api;
set local search_path=extensions,pg_catalog;
select no_plan();
select ok(not has_function_privilege('cuevo_api','internal.begin_authorized_teacher_insight_run(text,text,uuid,jsonb,text)','EXECUTE'),'runtime cannot bypass synthetic population accounting wrapper');
select ok(not has_function_privilege('cuevo_api','internal.begin_intelligence_run(text,text,uuid,jsonb,text)','EXECUTE'),'runtime cannot call the original numeric reservation implementation');
select ok(not has_function_privilege('authenticated','internal.begin_teacher_insight_run(text,text,uuid,jsonb,text)','EXECUTE'),'Data API cannot reserve live model runs');
select ok(not has_table_privilege('authenticated','app.intelligence_runs','SELECT,INSERT,UPDATE,DELETE'),'model accounting remains private');
insert into app.intelligence_policies(school_id,version,fixture_enabled,live_enabled,approved_by)values('10000000-0000-4000-8000-000000000001',1,true,true,'20000000-0000-4000-8000-000000000002')on conflict(school_id)do update set fixture_enabled=true,live_enabled=true,version=1,data_classification='SCHOOL_CUSTOM_NUMERIC',allowed_actions=array['GUIDED_PRACTICE','REVIEW_FEEDBACK']::text[];
-- The live accounting test explicitly approves its own rollback-only school cap.
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000001',true);
select internal.approve_intelligence_budget(jsonb_build_object('currency','USD','schoolDailyLimit',100000,'actorDailyLimit',100000,'maxConcurrentRuns',100,'expectedVersion',coalesce((internal.read_intelligence_budget()->'policy'->>'version')::integer,0),'confirmApproval',true,'reason','Explicit rollback-only accounting fixture ceiling.'),'accounting-school-cap',repeat('d',64),'accounting-cap');reset role;
create function pg_temp.accounting_execution_manifest()returns jsonb language sql immutable as $$select '{"version":"teacher-insight-1","purpose":"NEXT_LEARNING_ACTION","capabilities":["GROUNDED_EXPLANATION","RECOMMENDATION"],"mode":"LIVE","provider":"azure-foundry","model":"configured","promptId":"next-learning-action","promptVersion":"1","promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077","promptSource":"SOURCE_CONTROLLED_TASK_POLICY","promptEffectiveAt":"2026-10-01T00:00:00Z","evaluationVersion":"source-78-checked-evidence-1","dataClassification":"SCHOOL_CUSTOM_NUMERIC","providerDataPolicy":"SYNTHETIC_ONLY","maxOutputTokens":1000,"timeoutMs":10000,"maxCost":1}'::jsonb$$;grant execute on function pg_temp.accounting_execution_manifest()to cuevo_api;
set local role cuevo_api;select internal.approve_intelligence_execution(pg_temp.accounting_execution_manifest(),'accounting-manifest');reset role;
create temporary table accounting_fixture(baseline_id uuid,reservation jsonb,response jsonb);
grant select,insert,update on accounting_fixture to cuevo_api;
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
do $$declare c uuid;a uuid;s uuid;m uuid;r uuid;begin
 insert into app.courses(school_id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001',"authorization".actor_id(),'Accounting synthetic fixture','School authored','PUBLISHED')returning id into c;
 insert into app.assessments(school_id,course_id,created_by,title,instructions,max_score)values('10000000-0000-4000-8000-000000000001',c,"authorization".actor_id(),'Baseline','Teacher authored task',10)returning id into a;
 perform internal.link_assessment_reference(a,'61000000-0000-4000-8000-000000000001',1);
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
 insert into app.submissions(school_id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001',a,"authorization".actor_id(),'Synthetic source')returning id into s;
 perform set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
 m:=internal.mark_submission(s,0,'Reviewed feedback',2,0,true);r:=internal.release_marking(m,1,false);
 insert into accounting_fixture(baseline_id)values(r);
end$$;
reset role;
update app.people set synthetic=false where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
select throws_ok($$select internal.begin_teacher_insight_run('real-data-denied','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',(select baseline_id from accounting_fixture),'{"mode":"LIVE","provider":"azure-foundry","model":"configured","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1,"costBasis":"BUDGET_RESERVATION","syntheticOnly":true,"globalDailyBudget":1000000,"promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077"}'::jsonb||jsonb_build_object('executionManifest',pg_temp.accounting_execution_manifest()),'request')$$,'42501',null,'real learner is denied before reservation/model traffic');
reset role;
select is((select count(*)from app.intelligence_runs where command_key='real-data-denied'),0::bigint,'denied real population creates no model attempt');
update app.people set synthetic=true where school_id='10000000-0000-4000-8000-000000000001'and actor_id='20000000-0000-4000-8000-000000000012';
set local role cuevo_api;
update accounting_fixture set reservation=internal.begin_teacher_insight_run('reserved-live','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',baseline_id,'{"mode":"LIVE","provider":"azure-foundry","model":"configured","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1,"costBasis":"BUDGET_RESERVATION","syntheticOnly":true,"globalDailyBudget":1000000,"promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077"}'::jsonb||jsonb_build_object('executionManifest',pg_temp.accounting_execution_manifest()),'request-reserve');
select throws_ok($$select internal.complete_intelligence_run((select(reservation->>'runId')::uuid from accounting_fixture),(select(reservation->>'leaseToken')::uuid from accounting_fixture),jsonb_build_object('evidenceIds',jsonb_build_array((select reservation->'context'->'evidenceId'from accounting_fixture)),'facts',jsonb_build_array((select (reservation->'context')-'insight'-'allowedActions'from accounting_fixture)||jsonb_build_object('kind','NUMERIC_RESULT')),'action','GUIDED_PRACTICE','reason','REVIEW_RECORDED_RESULT','limitation','SINGLE_RESULT_NOT_CAUSAL'),'{"inputTokens":40,"outputTokens":80,"cost":0,"costBasis":"BUDGET_RESERVATION","latencyMs":1}','request')$$,'22023',null,'reservation cannot masquerade as zero live spend');
update accounting_fixture set response=internal.complete_intelligence_run((reservation->>'runId')::uuid,(reservation->>'leaseToken')::uuid,jsonb_build_object('evidenceIds',jsonb_build_array(reservation->'context'->'evidenceId'),'facts',jsonb_build_array(((reservation->'context')-'insight'-'allowedActions')||jsonb_build_object('kind','NUMERIC_RESULT')),'action','GUIDED_PRACTICE','reason','REVIEW_RECORDED_RESULT','limitation','SINGLE_RESULT_NOT_CAUSAL'),'{"inputTokens":40,"outputTokens":80,"cost":1,"costBasis":"BUDGET_RESERVATION","latencyMs":1}','request-complete');
select is((select response->>'status'from accounting_fixture),'AWAITING_HUMAN','real provider usage never approves an intervention');
select throws_ok($$select internal.begin_teacher_insight_run('reserved-live','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb',(select baseline_id from accounting_fixture),'{"mode":"LIVE","provider":"azure-foundry","model":"configured","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1,"costBasis":"CONFIGURED_TOKEN_RATES","syntheticOnly":true,"globalDailyBudget":1000000,"promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077"}'::jsonb||jsonb_build_object('executionManifest',pg_temp.accounting_execution_manifest()),'request-replay')$$,'22023',null,'a changed accounting schedule cannot relabel original-key replay');
select is((internal.read_intelligence_metrics(30,'LIVE')->>'totalCost')::numeric,0::numeric,'reserved budget is excluded from estimated spend');
select is((internal.read_intelligence_metrics(30,'LIVE')->'costAccounting'->>'reservedBudget')::numeric,1::numeric,'reservation is separately disclosed');
select ok(internal.read_intelligence_metrics(30,'LIVE')->'costAccounting'->'billedCost'='null'::jsonb,'billed provider cost remains unknown');
reset role;
select is((select input_tokens from app.intelligence_runs where command_key='reserved-live'),40,'actual provider input usage is persisted');
select is((select cost_basis from app.intelligence_runs where command_key='reserved-live'),'BUDGET_RESERVATION','accounting basis is immutable provenance');
select throws_ok($$update app.intelligence_runs set cost_basis='CONFIGURED_TOKEN_RATES'where command_key='reserved-live'$$,'55000',null,'completed cost history cannot be relabeled');
set local role cuevo_api;
update accounting_fixture set reservation=internal.begin_teacher_insight_run('unknown-failed-live','cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc',baseline_id,'{"mode":"LIVE","provider":"azure-foundry","model":"configured","promptId":"next-learning-action","promptVersion":"1","policyVersion":1,"timeoutMs":10000,"maxTokens":1000,"maxCost":1,"costBasis":"BUDGET_RESERVATION","syntheticOnly":true,"globalDailyBudget":1000000,"promptDigest":"a54af580544321d5cd3d9b212f423dd01bb4599a2ce3ec7a2bf9d3c32dfe5077"}'::jsonb||jsonb_build_object('executionManifest',pg_temp.accounting_execution_manifest()),'request-failed');
select internal.fail_intelligence_run((reservation->>'runId')::uuid,(reservation->>'leaseToken')::uuid,'INTELLIGENCE_PROVIDER_FAILED','request-failed')from accounting_fixture;
select is((internal.read_intelligence_metrics(30,'LIVE')->'costAccounting'->>'reservedBudget')::numeric,2::numeric,'failed model attempt retains its unknown-cost reservation');
select is((internal.read_intelligence_metrics(30,'LIVE')->'costAccounting'->>'unknownBilledCostRuns')::integer,2,'unknown completed/failed charges are counted');
reset role;
select *from finish();
rollback;
